from layout import *

def diagnosis():
    page('Промышленные журналы испытаний','Какие результаты передать следующему исполнителю',
         'Когда ещё два результата меняют порядок следующих проверок, их стоит передать. Для многих сессий порядок можно восстановить из общей истории.')
    p('На девяти системах Westermo наблюдаем шесть результатов тестов. Исполнитель уже видит самый свежий результат. Отправитель выбирает ещё два из пяти, чтобы приблизить решение исполнителя с полными данными. Читатель оценивает риск по 15 прошлым сессиям и ставит в начало очереди 10% оставшихся тестов. Основная метрика — доля фактических падений в этом начале очереди. Системы имеют равный вес.')
    tbl(['Что сохранить','Westermo','Независимые ABB'],[
        ['Два недавних результата','62,53%','46,99%'],['Два самых неожиданных','62,82%','47,49%'],
        ['Два результата по ожидаемому решению','62,99%','47,42%'],
        ['Тот же отправитель без учёта общей записи','62,96%','—']], [9.0,3.5,4.6])
    p('На Westermo преимущество над свежестью составило 0,46 п.п. (95% ДИ по системам от +0,29 до +0,61). Вклад явного учёта общей записи всего +0,03 п.п. (от −0,06 до +0,13). На ABB простое правило неожиданности впереди на 0,07 п.п.')
    h('Сколько данных нужно для того же решения')
    p('В другой проверке каждому читателю доступны две последние пробы. Ищем кратчайшее сообщение, при котором выбранные верхние 10% тестов совпадают с решением фиксированного учителя. В 2 027 сессиях N/B достаточно передать 387 из 4 054 возможных записей. С заголовками это 3 188 вместо 14 189 байт. В 784 сессиях I/M достаточно 37 из 1 568 записей (895 вместо 5 488 байт).')
    p('Равенство очередей задано процедурой. Экспериментальным результатом является степень сжатия. Дешёвое правило наибольшей неожиданности на N/B использует 3 284 байта и находит 4 047 падений против 4 039. Объём сообщения не включает исходные пробы и расчёт решения учителя.')
    source('Исходные системы и условное ранжирование · Torbunova et al.',ar('2402.02925'))

def masking():
    page('Внешняя воспроизводимая политика','Что сохраняется при маскировании наблюдений',
         'Аргументы прежних действий часто уже содержат нужный агенту фрагмент. Их удаление только из базового метода заметно завышает возможный выигрыш.')
    p('В работе Lindenbauer et al. M10 скрывает старые ответы инструментов, сохраняя задачу и все действия. Мы исполнили их исходный класс LastNObservations с n=10 и polling=1 на упорядоченных сообщениях SWE-smith. Для каждого прерывания проверили наличие точной строки следующей исторически принятой замены по тому же пути. Дословный текст должен лежать в одном непрерывном фрагменте либо в одном аргументе редактора.')
    tbl(['Информация у читателя','Окна, где M10 уже скрывает данные','Все окна'],[
        ['Десять последних ответов','561 / 925','847 / 1 325'],
        ['Только аргументы действий','594 / 925','681 / 1 325'],
        ['Ответы и аргументы вместе','741 / 925','1 074 / 1 325'],
        ['То же + до 256 токенов старых наблюдений','744 / 925','1 077 / 1 325'],
        ['Все прошлые ответы, без аргументов','703 / 925','989 / 1 325']], [8.3,5.25,3.55])
    p('После десяти ответов учёт доступных аргументов добавил 180 попаданий из 925, или +19,46 п.п. (95% ДИ с ресэмплингом по задачам от +16,44 до +22,92). Дополнительные старые фрагменты улучшили результат всего в трёх окнах. Пропуск дословных дубликатов уменьшил их объём с 191 701 до 186 739 токенов суммарно, при тех же 744 попаданиях.')
    h('Что ограничивает перенос')
    p('Использованы повторно изученные 408 траекторий, 170 задач, 14 проектов. В подмножестве после включения маски — 268 траекторий и 127 задач. Исходные программные действия не исполнялись. Содержание сохранённой команды описывает прошлую версию файла. Проверить применимость к текущему файлу можно только по его актуальной версии.')
    source('Оригинальный процессор и конфигурация M10 · JetBrains Research','https://github.com/JetBrains-Research/the-complexity-trap/tree/bf15b5fb7d279679035a007ac9a81084d6b9a89a')

def policy():
    page('Повторный анализ опубликованных прогонов','Помогает ли история выбрать способ сжатия',
         'Выбор стратегии по прошлым задачам того же репозитория дал восемь решённых задач меньше простого постоянного M10.')
    p('В архиве The Complexity Trap доступны исходы и стоимость отдельных прогонов SWE-agent. Мы сверили 7 487 строк основных конфигураций с официальными отчётами оценщика. Из 2 500 возможных сочетаний модели и задачи 2 487 имеют наблюдаемые исходы всех трёх стратегий. Одна и та же задача всегда входит в один из пяти фолдов при любой модели. Модель и репозиторий новой задачи известны.')
    p('Пять конфигураций включают Gemini 2.5 Flash с рассуждением и без него, Qwen3-Coder 480B, а также Qwen3-32B с рассуждением и без него. Для них в полном парном анализе осталось соответственно 496, 493, 498, 500 и 500 задач.')
    tbl(['Как выбирается история для агента','Решено / 2 487','Σ стоимости¹'],[
        ['Без сжатия','832','1 926,97'],['Постоянная маска M10','832','1 014,16'],
        ['Резюме от модели','810','1 059,87'],['Общая стратегия по истории обучения','827','1 029,12'],
        ['Стратегия по истории репозитория','824','1 078,79']], [8.5,4.0,4.6])
    p('¹ Суммируем округлённые авторские поля cost и summary_cost. Это оценка для опубликованных траекторий, без нового инференса. На каждой обучающей задаче открывался исход одной из трёх стратегий, выбранной по хешу. Историческая полезность учитывала исход решения и стоимость. Обменный коэффициент 0,1. Локальные оценки сглажены восемью наблюдениями глобальной политики.')
    p('Против M10 новая схема выиграла в 110 парах и проиграла в 118. Эффект −0,32 п.п., 95% ДИ по 12 репозиториям от −1,66 до +0,38. Даже когда при обучении доступны все три исхода на задачу, локальный выбор даёт 814, а глобальный — 826 решённых.')
    p('Для 14 из 15 конфигураций номинальные доли решения согласуются с таблицей авторов. Для Qwen3-Coder-480B без сжатия оценщик сообщает 267/500, таблица bootstrap — 266/499. Мы сохранили оба знаменателя. Для тех же моделей и тех же 500 задач воспроизведён расчёт из уже выполненных прогонов. Новое независимое разыгрывание траекторий здесь не проводилось.')
    source('Статья и описание опорного сравнения · Lindenbauer et al.',ar('2508.21433'))

def literature():
    page('Состояние области','Какие идеи уже проверены другими группами',
         'Вклад статьи придётся сформулировать точнее идеи «дать агенту недостающие сведения». На эту постановку уже есть отдельный бенчмарк и сильный метод.')
    tbl(['Работа','Механизм и граница сопоставления'],[
      ['Feng et al. · SERBench','MSS-Complement собирает комплект свидетельств для текущего решения. Три семантических шага. На закрытых 500 состояниях полное покрытие 73,0% при пяти и 80,6% при восьми объектах.'],
      ['Wang et al. · Ledger','Детерминированный журнал наблюдений и изменений проверяет актуальность повторных действий. На 500 SWE-bench Verified результат mini-swe-agent с GPT-5 mini вырос с 56,2 до 64,2% у авторов.'],
      ['Shi et al. · SWE-Pruner','Обученный модуль 0,6B отбирает строки по цели. В SWE-Pruner Pro используются внутренние состояния модели. Это релевантные сравнения для отсечения кода при чтении.'],
      ['Luo et al. · CAMP-II','Обучает агента вести переживающие сброс файлы обычными командами. CAMG-II охватывает пять классов задач. Внешние проверки включают Terminal-Bench и SWE-Bench Pro.'],
      ['Kumar и Pandey · TurnCost','В наблюдении 600 траекторий число ходов объясняло больше вариации стоимости, чем средний размер наблюдения. Для сравнения расходов нужны логи кэша и обращений к модели.']], [4.9,12.2],True)
    p('Два свежих направления из переписки дополняют эту картину. MIRIX-2.0 организует долговременную память для нескольких агентов. Evidence-Linked Memory показывает опасность неверно перенесённого урока. Их задачи и единицы результата различаются с одношаговым редактором.')
    h('Работа с фотографии')
    p('На третьем слайде прямо указана MemOS 1.0 и выделены параметрическая память, активации и текст. Эту систему описывают Li et al. На основном keynote ICDM 14 ноября выступала My T. Thai с другой темой. В tutorial того же дня участвовал соавтор MemOS Haofen Wang из Tongji. Публичной привязки первых двух иллюстраций и имени лектора к этому комплекту фотографий не установлено.')
    source('MemOS · Li et al.',ar('2507.03724'))
    source('ICDM 2026 · Программа tutorial','https://icdm2026.neu.edu.cn/Tutorials/list.htm')
    source('Ledger · детерминированное управление действиями',ar('2608.00808'))
    source('CAMP-II · обучение чтению и записи в рабочие файлы',ar('2611.14009'))
    source('SWE-Pruner Pro · отбор строк кодовой моделью',ar('2607.18213'))
    source('REM · выдача подробного опыта при затруднении',ar('2610.27377'))
